CREATE TABLE "task_definitions" (
"id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"type" TEXT NOT NULL,"assignedMembershipId" TEXT,"createdByMembershipId" TEXT,"priority" TEXT NOT NULL,"status" TEXT NOT NULL,"payload" JSONB NOT NULL,"nextDueAt" TIMESTAMP(3),"version" INTEGER NOT NULL DEFAULT 1,"legacyOrigin" TEXT,"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "task_definitions_assigned_fk" FOREIGN KEY("tenantId","assignedMembershipId") REFERENCES "tenant_memberships"("tenantId","id") ON DELETE SET NULL ("assignedMembershipId"),CONSTRAINT "task_definitions_creator_fk" FOREIGN KEY("tenantId","createdByMembershipId") REFERENCES "tenant_memberships"("tenantId","id") ON DELETE SET NULL ("createdByMembershipId"),CONSTRAINT "task_definitions_tenantId_id_key" UNIQUE("tenantId","id"),CONSTRAINT "task_definitions_status_check" CHECK("status" IN ('active','paused','completed')),CONSTRAINT "task_definitions_priority_check" CHECK("priority" IN ('low','medium','high')));
CREATE INDEX "task_definitions_tenantId_status_nextDueAt_idx" ON "task_definitions"("tenantId","status","nextDueAt");
CREATE TABLE "task_occurrences" (
"id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"lastError" TEXT,"snapshot" JSONB NOT NULL,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "task_occurrences_tenantId_taskId_id_key" UNIQUE("tenantId","taskId","id"),CONSTRAINT "task_occurrences_taskId_dueAt_key" UNIQUE("taskId","dueAt"),CONSTRAINT "task_occurrences_tenantId_id_key" UNIQUE("tenantId","id"),CONSTRAINT "task_occurrences_task_fk" FOREIGN KEY("tenantId","taskId") REFERENCES "task_definitions"("tenantId","id") ON DELETE RESTRICT);
CREATE INDEX "task_occurrences_tenantId_dueAt_status_idx" ON "task_occurrences"("tenantId","dueAt","status");
CREATE TABLE "task_deliveries" (
"id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL,"occurrenceId" TEXT NOT NULL,"channel" TEXT NOT NULL,"destination" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'pending',"payload" JSONB NOT NULL,"availableAt" TIMESTAMP(3) NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"claimedAt" TIMESTAMP(3),"messageId" TEXT,"notificationId" TEXT,"lastError" TEXT,"sentAt" TIMESTAMP(3),"dismissedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "task_deliveries_occurrenceId_channel_destination_key" UNIQUE("occurrenceId","channel","destination"),CONSTRAINT "task_deliveries_occurrence_fk" FOREIGN KEY("tenantId","occurrenceId") REFERENCES "task_occurrences"("tenantId","id") ON DELETE RESTRICT);
CREATE INDEX "task_deliveries_tenantId_status_availableAt_idx" ON "task_deliveries"("tenantId","status","availableAt");
CREATE TABLE "task_smtp_accounts" (
"id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL REFERENCES "tenants"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"host" TEXT NOT NULL,"port" INTEGER NOT NULL,"secure" BOOLEAN NOT NULL,"username" TEXT NOT NULL,"fromAddress" TEXT NOT NULL,"fromName" TEXT NOT NULL,"credential" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT TRUE,"lastVerifiedAt" TIMESTAMP(3),"archivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
CONSTRAINT "task_smtp_accounts_tenantId_id_key" UNIQUE("tenantId","id"));
CREATE INDEX "task_smtp_accounts_tenantId_archivedAt_idx" ON "task_smtp_accounts"("tenantId","archivedAt");
CREATE TABLE "task_settings" ("tenantId" TEXT PRIMARY KEY REFERENCES "tenants"("id") ON DELETE CASCADE,"payload" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "task_history" ("id" TEXT PRIMARY KEY,"tenantId" TEXT NOT NULL,"taskId" TEXT NOT NULL,"occurrenceId" TEXT,"action" TEXT NOT NULL,"membershipId" TEXT,"payload" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "task_history_occurrence_fk" FOREIGN KEY("tenantId","taskId","occurrenceId") REFERENCES "task_occurrences"("tenantId","taskId","id") ON DELETE RESTRICT,CONSTRAINT "task_history_membership_fk" FOREIGN KEY("tenantId","membershipId") REFERENCES "tenant_memberships"("tenantId","id") ON DELETE SET NULL ("membershipId"),CONSTRAINT "task_history_task_fk" FOREIGN KEY("tenantId","taskId") REFERENCES "task_definitions"("tenantId","id") ON DELETE RESTRICT);
CREATE INDEX "task_history_tenantId_taskId_createdAt_idx" ON "task_history"("tenantId","taskId","createdAt");
